.venv/bin/python - <<'PY'
import ast
samples = {
    'direct': 'breakpoint()\n',
    'attr': 'pdb.set_trace()\n',
    'multi_import': 'import os, pdb, ipdb\n',
    'from_import': 'from pdb import (\n    set_trace,\n    post_mortem,\n)\n',
    'relative': 'from .pdb import set_trace\n',
}
for name, source in samples.items():
    print(name)
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, (ast.Call, ast.Import, ast.ImportFrom, ast.alias)):
            print(type(node).__name__, ast.dump(node, include_attributes=True))
